<?php
declare(strict_types=1);require_once __DIR__.'/config/ai_analytics.php';
$error=null;$success=null;$queue=[];$published=[];$csrf='';
try{$pdo=role_portal_db();role_portal_ensure($pdo);aia_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user){header('Location: ../login.php');exit;}if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php');exit;}$orgId=pscms_org_id($pdo);$csrf=security_step17_csrf();
 if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'publish');$id=(int)($_POST['question_id']??0);if($action==='unpublish'){$s=$pdo->prepare("UPDATE public_ai_verified_answers SET status='draft',updated_by=?,updated_at=NOW() WHERE id=? AND organization_id=?");$s->execute([(int)$user['id'],$id,$orgId]);$success='Answer removed from the public AI knowledge feed.';}else{$answer=trim((string)($_POST['verified_answer']??''));$category=substr(trim((string)($_POST['category']??'General')),0,80)?:'General';if(mb_strlen($answer)<10)throw new RuntimeException('Write a meaningful verified answer before publishing.');$s=$pdo->prepare("SELECT question_text FROM public_ai_unanswered WHERE id=? AND organization_id=?");$s->execute([$id,$orgId]);$question=(string)$s->fetchColumn();if($question==='')throw new RuntimeException('Question was not found.');$s=$pdo->prepare("INSERT INTO public_ai_verified_answers(organization_id,source_question_id,question_text,verified_answer,category,status,created_by,updated_by) VALUES(?,?,?,?,?,'published',?,?) ON DUPLICATE KEY UPDATE question_text=VALUES(question_text),verified_answer=VALUES(verified_answer),category=VALUES(category),status='published',updated_by=VALUES(updated_by),updated_at=NOW()");$s->execute([$orgId,$id,$question,$answer,$category,(int)$user['id'],(int)$user['id']]);$pdo->prepare("UPDATE public_ai_unanswered SET status='resolved',resolution_note='Published to verified AI knowledge.',resolved_by=?,resolved_at=NOW() WHERE id=? AND organization_id=?")->execute([(int)$user['id'],$id,$orgId]);security_step17_audit($pdo,(int)$user['id'],'ai_verified_answer_published','public_ai_unanswered',$id,['category'=>$category]);$success='Verified answer published to both AI knowledge feeds.';}}
 $s=$pdo->prepare("SELECT u.* FROM public_ai_unanswered u LEFT JOIN public_ai_verified_answers v ON v.organization_id=u.organization_id AND v.source_question_id=u.id AND v.status='published' WHERE u.organization_id=? AND u.status IN('open','reviewing') AND v.id IS NULL ORDER BY u.created_at DESC LIMIT 100");$s->execute([$orgId]);$queue=$s->fetchAll();$published=aia_verified_answers($pdo,$orgId);
}catch(Throwable $e){$error=$e->getMessage();}
function aik_h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>AI Knowledge Manager</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>.km-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:14px;margin-top:14px}.km-card{padding:17px;border:1px solid #dce7e0;border-radius:16px;background:#fff}.km-item{margin-top:11px;padding:14px;border:1px solid #e0e9e4;border-radius:13px;background:#fbfdfc}.km-item p{margin:0 0 9px}.km-form{display:grid;grid-template-columns:160px 1fr auto;gap:8px}.km-form input,.km-form textarea{border:1px solid #d7e3dc;border-radius:9px;padding:9px}.km-form textarea{grid-column:1/-1;min-height:80px;resize:vertical}.km-form button{border:0;border-radius:9px;background:#167548;color:#fff;padding:9px 13px;font-weight:800}.km-meta{color:#6b7d73;font-size:.68rem}.km-live{display:flex;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid #e6ede9}.km-live form button{border:1px solid #e2cbc7;border-radius:8px;background:#fff5f3;color:#9a3c2f;padding:6px 8px}@media(max-width:900px){.km-grid{grid-template-columns:1fr}}@media(max-width:600px){.km-form{grid-template-columns:1fr}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>AI Knowledge Manager</small></span></a><div class="os-top-actions"><a class="os-btn" href="ai_improvement_dashboard.php">Analytics</a><a class="os-btn primary" href="customer_site_manager.php">Site Manager</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero"><div class="os-kicker">REVIEW • VERIFY • PUBLISH</div><h1>Turn unanswered questions into trusted AI knowledge.</h1><p>Only an admin-approved answer is published. Medical diagnosis, guaranteed results and unverified product claims must not be added.</p></section><?php if($error):?><div class="pp-alert bad" style="margin-top:14px"><?=aik_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good" style="margin-top:14px"><?=aik_h($success)?></div><?php endif;?><section class="km-grid"><article class="km-card"><h2>Needs Verified Answer</h2><p class="km-meta"><?=count($queue)?> question(s) awaiting review</p><?php if(!$queue):?><p class="km-meta">The review queue is clear.</p><?php endif;?><?php foreach($queue as $r):?><div class="km-item"><p><b><?=aik_h((string)$r['question_text'])?></b></p><div class="km-meta"><?=aik_h((string)($r['page_path']?:'Unknown page'))?> • <?=aik_h((string)$r['created_at'])?></div><form method="post" class="km-form" style="margin-top:10px"><input type="hidden" name="csrf" value="<?=aik_h($csrf)?>"><input type="hidden" name="question_id" value="<?=(int)$r['id']?>"><input name="category" maxlength="80" value="General" placeholder="Category"><button type="submit">Verify & Publish</button><textarea name="verified_answer" maxlength="8000" required placeholder="Write the accurate, public-safe answer that AI may use..."></textarea></form></div><?php endforeach;?></article><article class="km-card"><h2>Published Knowledge</h2><p class="km-meta"><?=count($published)?> verified answer(s) currently live</p><?php foreach($published as $r):?><div class="km-live"><div><b><?=aik_h((string)$r['question_text'])?></b><div class="km-meta"><?=aik_h((string)$r['category'])?> • <?=aik_h((string)$r['updated_at'])?></div></div><form method="post"><input type="hidden" name="csrf" value="<?=aik_h($csrf)?>"><input type="hidden" name="action" value="unpublish"><input type="hidden" name="question_id" value="<?=(int)$r['id']?>"><button>Unpublish</button></form></div><?php endforeach;?></article></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
